// ===== โหนด 4.9 Parse AI Response : แปลงคำตอบของ Gemini เป็นข้อมูลที่ใช้ได้ (Run Once for Each Item) =====
// คำตอบดิบจากโหนด 4.7 หรือ 4.8
const res = $json;
// Gemini แจ้ง error มาโดยตรง (เช่น โควตาหมด คีย์ผิด)
if (res.error) {
  throw new Error('[Gemini Error] ' + (res.error.description || res.error.message || JSON.stringify(res.error)));
}
// ผู้สมัคร/ไฟล์ถูกบล็อกหรือไม่มีคำตอบ (candidates ว่าง) จะแจ้งสาเหตุแทนการ error แบบอ่านไม่รู้เรื่อง
const cand = res.candidates && res.candidates[0];
if (!cand) throw new Error('[Gemini Blocked] ' + JSON.stringify(res.promptFeedback || res).slice(0, 300));
// ดึงข้อความคำตอบ (อาจว่างถ้าตอบไม่จบ เช่น finishReason = MAX_TOKENS)
const raw = cand.content && cand.content.parts && cand.content.parts[0] && cand.content.parts[0].text;
if (!raw) throw new Error('[Gemini Empty] finishReason=' + cand.finishReason);
// เผื่อ AI ห่อคำตอบด้วย ```json ... ``` ให้ลอกออก
const cleaned = raw.trim().replace(/^```(?:json)?\s*/i, '').replace(/\s*```$/, '');
let parsed;
try {
  parsed = JSON.parse(cleaned);                                   // แปลงข้อความเป็น object
} catch (e) {
  throw new Error('[Parse Error] AI response is not valid JSON: ' + e.message + ' | raw: ' + raw.slice(0, 300));
}
// ปรับแต่ละรายการให้เป็นรูปแบบมาตรฐาน {criterion, confidence, evidence}
const fix = arr => (Array.isArray(arr) ? arr : []).map(i => {
  const c = Number(i && i.confidence);                            // แปลง confidence เป็นตัวเลข
  return {
    criterion: String((i && (i.criterion ?? i.tool ?? i.skill)) ?? ''), // รองรับกรณี AI ใช้ชื่อคีย์ผิด (tool/skill)
    confidence: Number.isFinite(c) ? c : 0,                       // ถ้าไม่ใช่ตัวเลข ให้เป็น 0 (กัน NaN ทำให้ผ่าน Gate โดยไม่ตั้งใจ)
    evidence: String((i && i.evidence) ?? '')                     // หลักฐานที่ AI อ้าง
  };
});
// ส่งต่อเฉพาะ 3 กลุ่มที่ระบบใช้
return {
  json: {
    must_have_evaluation: fix(parsed.must_have_evaluation),      // ทักษะที่ต้องมี
    preferred_evaluation: fix(parsed.preferred_evaluation),      // ทักษะที่ควรมี
    tool_evaluation: fix(parsed.tool_evaluation)                 // เครื่องมือ
  }
};

