// ===== โหนด 4.4 Finalize Prompt Payload : เลือกส่ง "ข้อความ" หรือ "ไฟล์ PDF" ให้ AI (Run Once for Each Item) =====
// ถ้ามีไฟล์แนบมากับ item นี้ แปลว่ามาจากสาขา 4.3 (PDF สแกน อ่านข้อความไม่ได้) ให้ส่งเป็นไฟล์ให้ AI มองภาพ
const hasFile = $input.item.binary && $input.item.binary.data;
if (hasFile) {
  return {
    json: {
      // prompt ต้องดึงจากโหนด 4.1 เพราะ item ในสาขานี้มาจากการดาวน์โหลดไฟล์ ไม่มี prompt ติดมา
      systemPrompt: $('4.1 Build Gemini Prompt').item.json.systemPrompt,
      resumeText: '',                                                                                  // โหมดภาพไม่ใช้ข้อความ
      resumeFileBase64: (await this.helpers.getBinaryDataBuffer($itemIndex, 'data')).toString('base64'), // แปลงไฟล์เป็น base64 ให้ Gemini
      resumeMimeType: $input.item.binary.data.mimeType || 'application/pdf'                           // ชนิดไฟล์ (ค่าเริ่มต้น PDF)
    }
  };
} else {
  // ไม่มีไฟล์ = ข้อความอ่านได้ ส่งเป็นข้อความตามปกติ
  return {
    json: {
      systemPrompt: $json.systemPrompt,   // prompt จากโหนด 4.1
      resumeText: $json.resumeText,       // ข้อความ Resume
      resumeFileBase64: null,             // ไม่มีไฟล์
      resumeMimeType: null
    }
  };
}

// ===== โหนด 1.3 Validate Input : ตรวจข้อมูลใบสมัครก่อนบันทึก (mode: Run Once for Each Item) =====
// ดึง item ที่ webhook รับเข้ามา (ประกอบด้วยข้อความจากฟอร์มและไฟล์แนบ)
const wh = $('1.1 Webhook - Application Intake').item;
// ข้อความฟอร์มอยู่ใน json.body ถ้าไม่มีให้ใช้ object ว่างกัน error
const raw = (wh.json && wh.json.body) || {};
// รายชื่อตำแหน่งที่เปิดรับ มาจากโหนด 1.2 (ผลตอบกลับเต็มของ Supabase จึงอยู่ใน $json.body)
const positions = (Array.isArray($json.body) ? $json.body : []).map(p => p.position_name);
// ค่าช่วงประสบการณ์ที่ยอมรับ ต้องตรงกับตัวเลือกในหน้าเว็บทุกตัวอักษร
const EXPERIENCE = ['ไม่มีประสบการณ์ (นักศึกษาจบใหม่)', '1-3 ปี', '3-5 ปี', 'มากกว่า 5 ปี'];
// ขนาดไฟล์สูงสุด 5 MB
const MAX_BYTES = 5 * 1024 * 1024;
// ฟังก์ชันตัดช่องว่างหน้าหลัง ถ้าไม่ใช่ข้อความให้คืนค่าว่าง
const clean = v => (typeof v === 'string' ? v.trim() : '');

// สร้างข้อมูลที่ "ทำความสะอาดแล้ว" เพื่อใช้ในขั้นตอนถัดไป
const body = {
  full_name: clean(raw.full_name),                              // ชื่อ-นามสกุล
  phone_number: clean(raw.phone_number),                         // เบอร์โทร
  email: clean(raw.email).toLowerCase(),                         // อีเมล (แปลงเป็นตัวพิมพ์เล็กเพื่อให้เช็คสมัครซ้ำได้แม่น)
  applied_position: clean(raw.applied_position),                 // ตำแหน่งที่สมัคร
  self_reported_experience_range: clean(raw.self_reported_experience_range) || null // ช่วงประสบการณ์ที่ผู้สมัครเลือก
};

// เก็บชื่อฟิลด์ที่ไม่ผ่านการตรวจ เพื่อบอกกลับผู้ส่ง
const errors = [];
// ชื่อต้องไม่ว่างและไม่ยาวเกิน 150 ตัวอักษร
if (!body.full_name || body.full_name.length > 150) errors.push('full_name');
// เบอร์โทรยาว 8-20 ตัว ใช้ได้เฉพาะตัวเลข + - ช่องว่าง ( )
if (!/^[0-9+\-\s()]{8,20}$/.test(body.phone_number)) errors.push('phone_number');
// อีเมลยาวไม่เกิน 254 ตัวและมีรูปแบบ ชื่อ@โดเมน.นามสกุล
if (body.email.length > 254 || !/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(body.email)) errors.push('email');
// ตำแหน่งต้องมีอยู่ในรายการที่เปิดรับสมัครอยู่จริง
if (!positions.includes(body.applied_position)) errors.push('applied_position');
// ช่วงประสบการณ์ต้องมีค่าและเป็นหนึ่งในตัวเลือกที่กำหนด
if (!body.self_reported_experience_range || !EXPERIENCE.includes(body.self_reported_experience_range)) errors.push('self_reported_experience_range');

// ไฟล์ Resume ที่แนบมาในฟิลด์ชื่อ "resume"
const file = wh.binary && wh.binary.resume;
if (!file) {
  // ไม่มีไฟล์แนบ
  errors.push('resume');
} else {
  // ต้องเป็น PDF เท่านั้น
  if (file.mimeType !== 'application/pdf') errors.push('resume_type');
  // n8n ให้ขนาดไฟล์เป็นข้อความ เช่น "245 kB" จึงแยกตัวเลขกับหน่วยออกมา
  const m = String(file.fileSize || '').match(/([\d.]+)\s*(B|kB|KB|MB|GB)/i);
  // ตารางแปลงหน่วยเป็นไบต์ (ใช้ตัวพิมพ์เล็กเป็นคีย์)
  const units = { b: 1, kb: 1024, mb: 1024 * 1024, gb: 1024 * 1024 * 1024 };
  // คำนวณจำนวนไบต์ ถ้าอ่านขนาดไม่ได้ให้เป็น null
  const bytes = m ? parseFloat(m[1]) * units[m[2].toLowerCase()] : null;
  // อ่านขนาดไม่ได้ หรือใหญ่เกินกำหนด ถือว่าไม่ผ่าน (ปฏิเสธไว้ก่อนเพื่อความปลอดภัย)
  if (bytes === null || bytes > MAX_BYTES) errors.push('resume_size');
}

// ส่งผล: valid = true เมื่อไม่มี error, errors = รายชื่อฟิลด์ที่ผิด, body = ข้อมูลที่ทำความสะอาดแล้ว
return { json: { valid: errors.length === 0, errors, body } };

// ===== โหนด 2.1 Attach Resume Binary : ตั้งชื่อไฟล์แบบสุ่ม และส่งต่อไฟล์ PDF ไปโหนดอัปโหลด (Run Once for Each Item) =====
// สร้างชื่อไฟล์แบบสุ่มเดาไม่ได้ (UUID v4) เพื่อไม่ให้เดาลิงก์ Resume ของผู้อื่นได้
const uuid = (typeof crypto !== 'undefined' && crypto.randomUUID)   // ใช้ crypto ของระบบถ้ามี (ปลอดภัยกว่า)
  ? crypto.randomUUID()                                             // สร้าง UUID ด้วย crypto
  : 'xxxxxxxx-xxxx-4xxx-yxxx-xxxxxxxxxxxx'.replace(/[xy]/g, c => {  // ถ้าไม่มี crypto ให้สร้างเองด้วยเลขสุ่ม
      const r = Math.random() * 16 | 0;                             // เลขสุ่ม 0-15
      return (c === 'x' ? r : (r & 3 | 8)).toString(16);            // ใส่ค่าตามรูปแบบ UUID v4 เป็นเลขฐาน 16
    });
// ส่งชื่อไฟล์ให้โหนดอัปโหลด และแนบไฟล์ PDF จาก webhook กลับมา (โหนดก่อนหน้าไม่มีไฟล์ จึงต้องดึงจากต้นทาง)
return { json: { file_name: uuid + '.pdf' }, binary: $('1.1 Webhook - Application Intake').item.binary };

// ===== โหนด 7.3 Build Retry Record : แปลงผู้สมัครที่ค้าง pending ให้อยู่ในรูปเดียวกับโหนด 2.3 =====
return {
  json: {
    __retry: true,                                                   // ธงให้โหนด 2.3 ส่งต่อโดยไม่สร้างรหัสใหม่
    candidate_id: $json.candidate_id,                                // รหัสผู้สมัครเดิม
    full_name: $json.full_name,
    phone_number: $json.phone_number,
    email: $json.email,
    applied_position: $json.applied_position,
    self_reported_experience_range: $json.self_reported_experience_range,
    resume_file_url: $json.resume_file_url                           // ไฟล์เดิมใน bucket ส่วนตัว
  }
};
